// canonical immutable message record (one per send, even on fan-out).
export const messages = sqliteTable("messages", {
  messageId: text("message_id").primaryKey(),
  fromName: text("from_name"),
  kind: text("kind"), // 'dm'|'thread'|'topic'|'notification'
  toName: text("to_name"), // agent name OR thread name OR topic
  threadId: text("thread_id"), // resolved internal id (hidden from agents)
  topic: text("topic"),
  summary: text("summary"),
  body: text("body"),
  provenance: text("provenance"), // stored provenance JSON
  project: text("project"), // project scope (every read is project-scoped)
  createdAt: integer("created_at"),
  fromAgentId: text("from_agent_id"),
  toAgentId: text("to_agent_id"),
  metadataJson: text("metadata_json"),
});

// per-recipient delivery state machine (the in_flight / transient queue).
export const inFlight = sqliteTable("in_flight", {
  inFlightId: text("in_flight_id").primaryKey(),
  messageId: text("message_id"), // FK -> messages.message_id
  recipientSession: text("recipient_session"), // FK -> sessions.session_id
  state: text("state").default("pending"), // pending|notified|delivered|acked
  deliveredAt: integer("delivered_at"),
  ackedAt: integer("acked_at"),
});

// threads: named, ids hidden from agents.
export const threads = sqliteTable("threads", {
  threadId: text("thread_id").primaryKey(),
  name: text("name"),
  project: text("project"),
  topic: text("topic"),
  description: text("description"),
  createdBy: text("created_by"),
  createdAt: integer("created_at"),
  archivedAt: integer("archived_at"),
  metadataJson: text("metadata_json"),
});

export const threadMembers = sqliteTable(
  "thread_members",
  {
    threadId: text("thread_id"),
    sessionName: text("session_name"),
    joinedAt: integer("joined_at"),
  },
  (t) => [primaryKey({ columns: [t.threadId, t.sessionName] })],
);

// topics / pub-sub.
export const topics = sqliteTable("topics", {
  topic: text("topic").primaryKey(),
  project: text("project"),
  createdAt: integer("created_at"),
});

export const subscriptions = sqliteTable(
  "subscriptions",
  {
    topic: text("topic"),
    subscriberSession: text("subscriber_session"),
    subGroup: text("sub_group"), // group = competing-consumer
    cursor: integer("cursor").default(0),
    subscribedAt: integer("subscribed_at"),
  },
  (t) => [primaryKey({ columns: [t.topic, t.subscriberSession] })],
);

// notifications push-in routing audit (who-gets-what).
export const notifications = sqliteTable("notifications", {
  notifId: text("notif_id").primaryKey(),
  source: text("source"),
  topic: text("topic"),
  hmacOk: integer("hmac_ok"),
  payload: text("payload"),
  routedTo: text("routed_to"), // resolved recipients (csv) at ingest
  createdAt: integer("created_at"),
});

