// notification sources. The daemon owns registration/rotation; the gateway read
// path uses the token only to verify signed producer pushes before enqueueing a
// `source.push` command intent.
export const sources = sqliteTable("sources", {
  name: text("name").primaryKey(),
  token: text("token"),
  topic: text("topic"),
  enabled: integer("enabled").default(1),
  createdAt: integer("created_at"),
  lastFiredAt: integer("last_fired_at"),
});

// routing_rules: standing route rules (by source and/or topic) → a recipient
// name or thread. Display-only projection used by the web console `listRoutingRules`
// (the daemon owns the authoritative routing config; this is the read shape).
export const routingRules = sqliteTable("routing_rules", {
  ruleId: text("rule_id").primaryKey(),
  source: text("source"),
  topic: text("topic"),
  toName: text("to_name"), // recipient: agent name or thread name
  project: text("project"),
  createdAt: integer("created_at"),
});

